const alphabet='abcdefghijklmnopqrstuvwxyz'.split('');
function getCipherMap(shift){
  return alphabet.reduce((m,c,i)=>{
    let idx=(i+shift)%alphabet.length;
    if(idx<=0) idx+=alphabet.length;
    m[c]=alphabet[idx];
    return m;
  },{});
}
console.log('shift 3, d->', getCipherMap(3).d, 'e->', getCipherMap(3).e, 'f->', getCipherMap(3).f, 'g->', getCipherMap(3).g, 'h->', getCipherMap(3).h);
console.log('shift -3, d->', getCipherMap(-3).d, 'e->', getCipherMap(-3).e, 'f->', getCipherMap(-3).f, 'g->', getCipherMap(-3).g, 'h->', getCipherMap(-3).h);
console.log('shift 0, a->', getCipherMap(0).a, 'b->', getCipherMap(0).b, 'z->', getCipherMap(0).z);
